    /// Waits for the next <c>OnRenderObject</c> message, which Unity sends after the scene's regular rendering
    /// finished, to let a script draw with the <c>GL</c> class (UniTask <c>IAsyncOnRenderObjectHandler</c>
    /// parity).
    /// </summary>
    public interface IOnityAsyncOnRenderObjectHandler
    {
        /// <summary>Waits for the next <c>OnRenderObject</c> message. Main thread only.</summary>
        /// <returns>A single-consumption task; canceled when the trigger is destroyed.</returns>
        OnityTask OnRenderObjectAsync();
    }

    public sealed partial class OnityAsyncTriggerHandler<T> : IOnityAsyncOnRenderObjectHandler
    {
        OnityTask IOnityAsyncOnRenderObjectHandler.OnRenderObjectAsync()
        {
            return WaitAsync();
        }
    }

    public static partial class OnityAsyncTriggerExtensions
    {
        /// <summary>Gets or adds the <see cref="OnityAsyncRenderObjectTrigger"/>. Main thread only.</summary>
        /// <param name="gameObject">Live owner GameObject.</param>
        /// <returns>The single <see cref="OnityAsyncRenderObjectTrigger"/> on the GameObject.</returns>
        /// <exception cref="ArgumentNullException"><paramref name="gameObject"/> is null.</exception>
        public static OnityAsyncRenderObjectTrigger GetAsyncRenderObjectTrigger(this GameObject gameObject)
        {
            return GetOrAddComponent<OnityAsyncRenderObjectTrigger>(gameObject);
        }

        /// <summary>Gets or adds the <see cref="OnityAsyncRenderObjectTrigger"/> on the component's GameObject. Main thread only.</summary>
        /// <param name="component">Live owner component.</param>
        /// <returns>The single <see cref="OnityAsyncRenderObjectTrigger"/> on the GameObject.</returns>
        /// <exception cref="ArgumentNullException"><paramref name="component"/> is null.</exception>
        public static OnityAsyncRenderObjectTrigger GetAsyncRenderObjectTrigger(this Component component)
        {
            return GetGameObject(component).GetAsyncRenderObjectTrigger();
        }
    }

    /// <summary>
    /// Trigger for the <c>OnRenderObject</c> message, which Unity sends after the scene's regular rendering
    /// finished, to let a script draw with the <c>GL</c> class (UniTask <c>AsyncRenderObjectTrigger</c>
    /// parity). The component itself is an <see cref="IOnityAsyncEnumerable{T}"/> of the raised messages. Main
    /// thread only.
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class OnityAsyncRenderObjectTrigger : OnityAsyncTriggerBase<Unit>
    {
        /// <summary>Creates a reusable handler; dispose it to unregister. Main thread only.</summary>
        /// <returns>A handler whose each <c>OnRenderObjectAsync()</c> waits for the next message.</returns>
        public IOnityAsyncOnRenderObjectHandler GetOnRenderObjectAsyncHandler()
        {
            return new OnityAsyncTriggerHandler<Unit>(this, false);
        }

        /// <summary>Creates a reusable handler bound to a token. Main thread only.</summary>
        /// <param name="cancellationToken">Cancels the pending wait and unregisters the handler.</param>
        /// <returns>A handler whose each <c>OnRenderObjectAsync()</c> waits for the next message.</returns>
        public IOnityAsyncOnRenderObjectHandler GetOnRenderObjectAsyncHandler(CancellationToken cancellationToken)
        {
            return new OnityAsyncTriggerHandler<Unit>(this, cancellationToken, false);
        }

        /// <summary>Waits for the next <c>OnRenderObject</c> message. Main thread only.</summary>
        /// <returns>A single-consumption task; canceled when the trigger is destroyed.</returns>
        public OnityTask OnRenderObjectAsync()
        {
            return ((IOnityAsyncOnRenderObjectHandler)new OnityAsyncTriggerHandler<Unit>(this, true)).OnRenderObjectAsync();
        }

        /// <summary>Waits for the next <c>OnRenderObject</c> message. Main thread only.</summary>
        /// <param name="cancellationToken">Cancels the wait.</param>
        /// <returns>A single-consumption task; canceled by the token or when the trigger is destroyed.</returns>
        public OnityTask OnRenderObjectAsync(CancellationToken cancellationToken)
        {
            return ((IOnityAsyncOnRenderObjectHandler)new OnityAsyncTriggerHandler<Unit>(this, cancellationToken, true)).OnRenderObjectAsync();
        }

        private void OnRenderObject()
        {
            RaiseEvent(Unit.Default);
        }
    }
#endregion

